    13→    internal sealed class GasLimitTxFilter(IChainHeadInfoProvider chainHeadInfoProvider, ITxPoolConfig txPoolConfig, ILogManager logManager)
    14→        : IIncomingTxFilter
    15→    {
    16→        private readonly ILogger _logger = logManager.GetClassLogger();
    17→        private readonly long _configuredGasLimit = txPoolConfig.GasLimit ?? long.MaxValue;
    18→
    19→        public AcceptTxResult Accept(Transaction tx, ref TxFilteringState state, TxHandlingOptions handlingOptions)
    20→        {
    21→            long gasLimit = Math.Min(chainHeadInfoProvider.BlockGasLimit ?? long.MaxValue, _configuredGasLimit);
    22→            if (tx.GasLimit > gasLimit)
    23→            {
    24→                Metrics.PendingTransactionsGasLimitTooHigh++;
    25→
    26→                if (_logger.IsTrace)
    27→                {
    28→                    _logger.Trace($"Skipped adding transaction {tx.ToString("  ")}, gas limit exceeded.");
    29→                }
    30→
    31→                bool isNotLocal = (handlingOptions & TxHandlingOptions.PersistentBroadcast) == 0;
    32→                return isNotLocal ?
    33→                    AcceptTxResult.GasLimitExceeded :
    34→                    AcceptTxResult.GasLimitExceeded.WithMessage($"Gas limit: {gasLimit}, gas limit of rejected tx: {tx.GasLimit}");
    35→            }
    36→
    37→            return AcceptTxResult.Accepted;
    38→        }
    39→    }
