    13→    public class ReceiptMessageDecoder : IRlpStreamDecoder<TxReceipt>, IRlpValueDecoder<TxReceipt>
    14→    {
    15→        private readonly bool _skipStateAndStatus;
    16→
    17→        public ReceiptMessageDecoder(bool skipStateAndStatus = false)
    18→        {
    19→            _skipStateAndStatus = skipStateAndStatus;
    20→        }
    21→        public TxReceipt Decode(RlpStream rlpStream, RlpBehaviors rlpBehaviors = RlpBehaviors.None)
    22→        {
    23→            Span<byte> span = rlpStream.PeekNextItem();
    24→            Rlp.ValueDecoderContext ctx = new Rlp.ValueDecoderContext(span);
    25→            TxReceipt response = Decode(ref ctx, rlpBehaviors);
    26→            rlpStream.SkipItem();
    27→
    28→            return response;
    29→        }
    30→
    31→        public TxReceipt Decode(ref Rlp.ValueDecoderContext ctx, RlpBehaviors rlpBehaviors = RlpBehaviors.None)
    32→        {
    33→            if (ctx.IsNextItemNull())
    34→            {
    35→                ctx.ReadByte();
    36→                return null;
    37→            }
    38→
    39→            TxReceipt txReceipt = new();
    40→            if (!ctx.IsSequenceNext())
    41→            {
    42→                ctx.SkipLength();
    43→                txReceipt.TxType = (TxType)ctx.ReadByte();
    44→            }
    45→
    46→            _ = ctx.ReadSequenceLength();
    47→            byte[] firstItem = ctx.DecodeByteArray();
    48→            if (firstItem.Length == 1 && (firstItem[0] == 0 || firstItem[0] == 1))
    49→            {
    50→                txReceipt.StatusCode = firstItem[0];
    51→                txReceipt.GasUsedTotal = (long)ctx.DecodeUBigInt();
    52→            }
    53→            else if (firstItem.Length is >= 1 and <= 4)
    54→            {
    55→                txReceipt.GasUsedTotal = (long)firstItem.ToUnsignedBigInteger();
    56→            }
    57→            else
    58→            {
    59→                txReceipt.PostTransactionState = firstItem.Length == 0 ? null : new Hash256(firstItem);
    60→                txReceipt.GasUsedTotal = (long)ctx.DecodeUBigInt();
    61→            }
    62→
    63→            txReceipt.Bloom = ctx.DecodeBloom();
    64→
    65→            int lastCheck = ctx.ReadSequenceLength() + ctx.Position;
    66→
    67→            int numberOfReceipts = ctx.PeekNumberOfItemsRemaining(lastCheck);
    68→            LogEntry[] entries = new LogEntry[numberOfReceipts];
    69→            for (int i = 0; i < numberOfReceipts; i++)
    70→            {
    71→                entries[i] = Rlp.Decode<LogEntry>(ref ctx, RlpBehaviors.AllowExtraBytes);
    72→            }
    73→            txReceipt.Logs = entries;
    74→
    75→            return txReceipt;
    76→        }
    77→
    78→        private (int Total, int Logs) GetContentLength(TxReceipt item, RlpBehaviors rlpBehaviors)
    79→        {
    80→            if (item is null)
    81→            {
    82→                return (0, 0);
    83→            }
    84→
    85→            int contentLength = 0;
    86→            contentLength += Rlp.LengthOf(item.GasUsedTotal);
    87→            contentLength += Rlp.LengthOf(item.Bloom);
    88→
    89→            int logsLength = GetLogsLength(item);
    90→            contentLength += Rlp.LengthOfSequence(logsLength);
    91→
    92→            bool isEip658Receipts = (rlpBehaviors & RlpBehaviors.Eip658Receipts) == RlpBehaviors.Eip658Receipts;
    93→
    94→            if (!_skipStateAndStatus)
    95→            {
    96→                contentLength += isEip658Receipts
    97→                    ? Rlp.LengthOf(item.StatusCode)
    98→                    : Rlp.LengthOf(item.PostTransactionState);
    99→            }
   100→
   101→            return (contentLength, logsLength);
   102→        }
   103→
   104→        private static int GetLogsLength(TxReceipt item)
   105→        {
   106→            int logsLength = 0;
   107→            for (var i = 0; i < item.Logs.Length; i++)
   108→            {
   109→                logsLength += Rlp.LengthOf(item.Logs[i]);
   110→            }
   111→
   112→            return logsLength;
   113→        }
   114→
   115→        /// <summary>
   116→        /// https://eips.ethereum.org/EIPS/eip-2718
   117→        /// </summary>
   118→        public int GetLength(TxReceipt item, RlpBehaviors rlpBehaviors)
   119→        {
   120→            (int Total, _) = GetContentLength(item, rlpBehaviors);
   121→            int receiptPayloadLength = Rlp.LengthOfSequence(Total);
   122→
   123→            bool isForTxRoot = (rlpBehaviors & RlpBehaviors.SkipTypedWrapping) == RlpBehaviors.SkipTypedWrapping;
   124→            int result = item.TxType != TxType.Legacy
   125→                ? isForTxRoot
   126→                    ? (1 + receiptPayloadLength)
   127→                    : Rlp.LengthOfSequence(1 + receiptPayloadLength) // Rlp(TransactionType || TransactionPayload)
   128→                : receiptPayloadLength;
   129→            return result;
   130→        }
   131→
   132→        public byte[] EncodeNew(TxReceipt? item, RlpBehaviors rlpBehaviors = RlpBehaviors.None)
   133→        {
   134→            if (item is null)
   135→            {
   136→                return Rlp.OfEmptySequence.Bytes;
   137→            }
   138→
   139→            int length = GetLength(item, rlpBehaviors);
   140→            RlpStream stream = new(length);
   141→            Encode(stream, item, rlpBehaviors);
   142→            return stream.Data.ToArray();
   143→        }
   144→
   145→        public void Encode(RlpStream rlpStream, TxReceipt item, RlpBehaviors rlpBehaviors = RlpBehaviors.None)
   146→        {
   147→            if (item is null)
   148→            {
   149→                rlpStream.EncodeNullObject();
   150→                return;
   151→            }
   152→
   153→            (int totalContentLength, int logsLength) = GetContentLength(item, rlpBehaviors);
   154→            int sequenceLength = Rlp.LengthOfSequence(totalContentLength);
   155→
   156→            bool isEip658Receipts = (rlpBehaviors & RlpBehaviors.Eip658Receipts) == RlpBehaviors.Eip658Receipts;
   157→
   158→            if (item.TxType != TxType.Legacy)
   159→            {
   160→                if ((rlpBehaviors & RlpBehaviors.SkipTypedWrapping) == RlpBehaviors.None)
   161→                {
   162→                    rlpStream.StartByteArray(sequenceLength + 1, false);
   163→                }
   164→
   165→                rlpStream.WriteByte((byte)item.TxType);
   166→            }
   167→
   168→            rlpStream.StartSequence(totalContentLength);
   169→            if (!_skipStateAndStatus)
   170→            {
   171→                if (isEip658Receipts)
   172→                {
   173→                    rlpStream.Encode(item.StatusCode);
   174→                }
   175→                else
   176→                {
   177→                    rlpStream.Encode(item.PostTransactionState);
   178→                }
   179→            }
   180→
   181→            rlpStream.Encode(item.GasUsedTotal);
   182→            rlpStream.Encode(item.Bloom);
   183→
   184→            rlpStream.StartSequence(logsLength);
   185→            LogEntry[] logs = item.Logs;
   186→            for (var i = 0; i < logs.Length; i++)
   187→            {
   188→                rlpStream.Encode(logs[i]);
   189→            }
   190→        }
   191→    }
   192→}
